-- Top performer = most laps, compute their LTC
SELECT ROUND(CAST(STDDEV_POP(lt.msec_val / 1000.0) AS numeric), 2) as best_ltc_score
FROM lap_times lt
WHERE lt.wheel_unit = (
    SELECT wheel_unit FROM lap_times GROUP BY wheel_unit ORDER BY COUNT(*) DESC LIMIT 1
);

